INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_accordion','Accordion','accordion','Data Display','A collapsible for displaying content.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","lucide-react"],"cssVars":{"theme":{"--animate-slide-up":"slideUp 0.2s ease-out","--animate-slide-down":"slideDown 0.2s ease-out"}},"css":{"@keyframes slideUp":{"from":{"height":"var(--height)"},"to":{"height":"0"}},"@keyframes slideDown":{"from":{"height":"0"},"to":{"height":"var(--height)"}}},"file":{"path":"registry/react/components/accordion.tsx","type":"registry:ui"}}','"use client";

import {
  Accordion as ArkAccordion,
  useAccordionContext,
} from "@ark-ui/react/accordion";
import { ChevronDownIcon } from "lucide-react";
import type React from "react";
import { cn } from "@/lib/utils";

export const useAccordion = useAccordionContext;

export const Accordion = (
  props: React.ComponentProps<typeof ArkAccordion.Root>
) => {
  const {
    collapsible = true,
    lazyMount = true,
    unmountOnExit = true,
    ...rest
  } = props;

  return (
    <ArkAccordion.Root
      collapsible={collapsible}
      data-slot="accordion"
      lazyMount={lazyMount}
      unmountOnExit={unmountOnExit}
      {...rest}
    />
  );
};

export const AccordionItem = (
  props: React.ComponentProps<typeof ArkAccordion.Item>
) => {
  const { className, ...rest } = props;

  return (
    <ArkAccordion.Item
      className={cn("flex flex-col border-b last:border-b-0", className)}
      data-slot="accordion-item"
      {...rest}
    />
  );
};

export const AccordionTrigger = (
  props: React.ComponentProps<typeof ArkAccordion.ItemTrigger>
) => {
  const { className, children, ...rest } = props;

  return (
    <ArkAccordion.ItemTrigger
      className={cn(
        "flex flex-1 items-center justify-between gap-3",
        "py-4",
        "text-left font-medium text-sm",
        "rounded-md border border-transparent",
        "outline-none",
        "transition-all",
        "disabled:pointer-events-none disabled:opacity-64 disabled:grayscale",
        "focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-ring/32",
        "[&_[data-state=open]>svg]:rotate-180",
        "motion-reduce:transition-none!",
        className
      )}
      data-slot="accordion-trigger"
      {...rest}
    >
      {children}

      <ArkAccordion.ItemIndicator data-slot="accordion-indicator">
        <ChevronDownIcon
          className={cn(
            "translate-y-0.5",
            "size-4",
            "shrink-0",
            "text-muted-foreground",
            "pointer-events-none",
            "transition-transform duration-300",
            "motion-reduce:transition-none!"
          )}
        />
      </ArkAccordion.ItemIndicator>
    </ArkAccordion.ItemTrigger>
  );
};

export const AccordionContent = (
  props: React.ComponentProps<typeof ArkAccordion.ItemContent>
) => {
  const { className, children, ...rest } = props;

  return (
    <ArkAccordion.ItemContent
      className={cn(
        "overflow-hidden rounded-md text-sm",
        "data-[state=open]:animate-slide-down",
        "data-[state=closed]:animate-slide-up",
        "motion-reduce:animate-none!",
        className
      )}
      data-slot="accordion-content"
      {...rest}
    >
      <div className="pt-0 pb-4">{children}</div>
    </ArkAccordion.ItemContent>
  );
};
