INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_alert-dialog','Alert Dialog','alert-dialog','Overlays','Dialog for displaying important content.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","tailwind-variants","lucide-react"],"registryDependencies":["https://bits.dakik.co.uk/r/button.json","https://bits.dakik.co.uk/r/dialog.json"],"file":{"path":"registry/react/components/alert-dialog.tsx","type":"registry:ui"}}','"use client";

