INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_announcement','Announcement','announcement','Feedback','Inline notice for short, prominent updates.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","tailwind-variants"],"registryDependencies":["https://bits.dakik.co.uk/r/badge.json"],"cssVars":{"light":{"destructive-foreground":"var(--color-red-700)","info":"var(--color-blue-500)","info-foreground":"var(--color-blue-700)","success":"var(--color-emerald-500)","success-foreground":"var(--color-emerald-700)","warning":"var(--color-amber-500)","warning-foreground":"var(--color-amber-700)"},"dark":{"destructive-foreground":"var(--color-red-400)","info":"var(--color-blue-500)","info-foreground":"var(--color-blue-400)","success":"var(--color-emerald-500)","success-foreground":"var(--color-emerald-400)","warning":"var(--color-amber-500)","warning-foreground":"var(--color-amber-400)"}},"file":{"path":"registry/react/components/announcement.tsx","type":"registry:ui"}}','"use client";

import { ark } from "@ark-ui/react/factory";
import type React from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "@/lib/utils";

export const announcementVariants = tv({
  base: [
    "group/announcement",
    "relative",
    "inline-flex min-w-0 max-w-full items-center gap-2",
    "py-0.5 ps-3 pe-3",
    "bg-input/4",
    "rounded-2xl border border-input",
    "transition-colors",
    "outline-none focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-ring/32",
    "[&_svg]:size-3.5 [&_svg]:shrink-0",
    "has-data-[slot=badge]:ps-0.5",
    "[button&,a&]:cursor-pointer",
    "[&>svg]:text-muted-foreground",
    "[a&]:hover:bg-input/12",
    "**:data-[slot=badge]:h-6.5 **:data-[slot=badge]:rounded-xl **:data-[slot=badge]:px-2 **:data-[slot=badge]:sm:text-xs",
    "[button&,a&]:pointer-coarse:after:absolute [button&,a&]:pointer-coarse:after:size-full [button&,a&]:pointer-coarse:after:min-h-11 [button&,a&]:pointer-coarse:after:min-w-11",
    "motion-reduce:transition-none!",
  ],
});

interface AnnouncementProps
  extends React.ComponentProps<typeof ark.div>,
    VariantProps<typeof announcementVariants> {
  /**
   * The ARIA role of the announcement.
   *
   * @default "status"
   */
  role?: "status" | "alert";
}

export const Announcement = (props: AnnouncementProps) => {
  const { className, role = "status", ...rest } = props;

  return (
    <ark.div
      className={cn(announcementVariants(), className)}
      data-slot="announcement"
      role={role}
      {...rest}
    />
