INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_card','Card','card','Layout','Displays content about a single subject.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","tailwind-variants"],"file":{"path":"registry/react/components/card.tsx","type":"registry:ui"}}','import { ark } from "@ark-ui/react/factory";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "@/lib/utils";

export const Card = (props: React.ComponentProps<typeof ark.div>) => {
