INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_data-list','Data List','data-list','Data Display','A list of label-value pairs.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react"],"file":{"path":"registry/react/components/data-list.tsx","type":"registry:ui"}}','"use client";

