INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_field','Field','field','Forms','Container for inputs, labels, and helper text.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","tailwind-variants"],"registryDependencies":["https://bits.dakik.co.uk/r/separator.json"],"file":{"path":"registry/react/components/field.tsx","type":"registry:ui"}}','"use client";

