INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_float','Float','float','Layout','Anchor an element to the edge of a container.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","tailwind-variants"],"file":{"path":"registry/react/components/float.tsx","type":"registry:ui"}}','"use client";

import { ark } from "@ark-ui/react/factory";
import type React from "react";
