INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_native-select','Native Select','native-select','Forms','Styled native HTML select element.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","lucide-react","tailwind-variants"],"registryDependencies":["https://bits.dakik.co.uk/r/field.json"],"file":{"path":"registry/react/components/native-select.tsx","type":"registry:ui"}}','"use client";

