INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_progress','Progress','progress','Feedback','Displays task progress with a linear indicator.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react"],"registryDependencies":["https://bits.dakik.co.uk/r/field.json"],"cssVars":{"theme":{"--animate-indeterminate":"indeterminate 1.5s ease-in-out infinite"}},"css":{"@keyframes indeterminate":{"0%":{"transform":"translateX(-100%)"},"100%":{"transform":"translateX(400%)"}}},"file":{"path":"registry/react/components/progress.tsx","type":"registry:ui"}}','"use client";

import {
  Progress as ArkProgress,
  useProgressContext,
} from "@ark-ui/react/progress";
import type React from "react";
import { cn } from "@/lib/utils";
import { FieldLabel } from "@/registry/react/components/field";

export const useProgress = useProgressContext;

interface ProgressProps
  extends Omit<React.ComponentProps<typeof ArkProgress.Root>, "value"> {
  /**
   * Shows indeterminate progress
   *
   * @default false
   */
  indeterminate?: boolean;
  /**
   * The value of the progress bar
   *
   * @default 0
   */
  value?: number;
}

export const Progress = (props: ProgressProps) => {
  const {
    value,
    orientation = "horizontal",
    indeterminate = false,
    className,
    children,
    ...rest
  } = props;

  return (
    <ArkProgress.Root
      className={cn(
        "flex flex-wrap gap-3",
        "data-[orientation=horizontal]:w-full",
        "data-[orientation=vertical]:-scale-y-100",
        className
      )}
      data-slot="progress"
      orientation={orientation}
      value={indeterminate ? null : value}
      {...rest}
    >
      {children}

      <ProgressTrack>
        <ProgressRange />
      </ProgressTrack>
    </ArkProgress.Root>
  );
};

export const ProgressTrack = (
  props: React.ComponentProps<typeof ArkProgress.Track>
) => (
  <ArkProgress.Track
    className={cn(
      "bg-input",
      "rounded-full",
      "overflow-x-hidden",
      "data-[orientation=horizontal]:h-2 data-[orientation=horizontal]:w-full",
      "data-[orientation=vertical]:h-full data-[orientation=vertical]:w-2"
    )}
    data-slot="progress-track"
    {...props}
  />
);

export const ProgressRange = (
  props: React.ComponentProps<typeof ArkProgress.Range>
) => (
  <ArkProgress.Range
    className={cn(
      "bg-primary",
      "transition-all duration-300 ease-out",
      "data-[orientation=horizontal]:h-full",
      "data-[orientation=vertical]:h-full",
      "motion-reduce:animate-none! motion-reduce:transition-none!",
      "data-[state=indeterminate]:w-1/3 data-[state=indeterminate]:animate-indeterminate! data-[state=indeterminate]:duration-100"
    )}
    data-slot="progress-range"
    {...props}
  />
);

export const ProgressValue = (
  props: React.ComponentProps<typeof ArkProgress.ValueText>
) => {
  const { className, ...rest } = props;

  return (
    <FieldLabel asChild>
      <ArkProgress.ValueText
        className={cn("ms-auto tabular-nums", className)}
        data-slot="progress-value"
        {...rest}
      />
    </FieldLabel>
  );
};
