INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_skip-nav','Skip Nav','skip-nav','Navigation','Lets keyboard users skip to main content.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react"],"file":{"path":"registry/react/components/skip-nav.tsx","type":"registry:ui"}}','"use client";

