INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_toast','Toast','toast','Feedback','Provides feedback on an action.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react","tailwind-variants","lucide-react"],"registryDependencies":["https://bits.dakik.co.uk/r/button.json","https://bits.dakik.co.uk/r/spinner.json"],"cssVars":{"light":{"destructive-foreground":"var(--color-red-700)","info":"var(--color-blue-500)","info-foreground":"var(--color-blue-700)","success":"var(--color-emerald-500)","success-foreground":"var(--color-emerald-700)","warning":"var(--color-amber-500)","warning-foreground":"var(--color-amber-700)"},"dark":{"destructive-foreground":"var(--color-red-400)","info":"var(--color-blue-500)","info-foreground":"var(--color-blue-400)","success":"var(--color-emerald-500)","success-foreground":"var(--color-emerald-400)","warning":"var(--color-amber-500)","warning-foreground":"var(--color-amber-400)"}},"file":{"path":"registry/react/components/toast.tsx","type":"registry:ui"}}','"use client";

import { Portal } from "@ark-ui/react/portal";
import {
  Toast as ArkToast,
  Toaster as ArkToaster,
  createToaster,
  useToastContext,
} from "@ark-ui/react/toast";
import {
  CircleAlertIcon,
  CircleCheckIcon,
  InfoIcon,
  TriangleAlertIcon,
  XIcon,
} from "lucide-react";
import type React from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/registry/react/components/button";
import { Spinner } from "@/registry/react/components/spinner";

export const useToast = useToastContext;

export const toast = createToaster({
  placement: "bottom-end",
  overlap: true,
  max: 3,
});

interface ToasterProps
  extends Omit<
    React.ComponentProps<typeof ArkToaster>,
    "toaster" | "children"
  > {
  /**
   * Toaster instance
   */
  toaster?: ReturnType<typeof createToaster>;
}

export const Toaster = (props: ToasterProps) => {
  const { toaster: toasterInstance = toast, className, style, ...rest } = props;

  return (
    <Portal>
      <ArkToaster
        className={cn(
          "w-[calc(100%-var(--viewport-offset-left))] sm:w-(--width)",
          "data-[align=center]:left-[calc(var(--viewport-offset-right)/2)]!",
          "sm:data-[align=center]:w-full",
          className
        )}
        style={{ "--width": "356px", ...style } as React.CSSProperties}
        toaster={toasterInstance}
        {...rest}
      >
        {(toastItem) => <ToastItem toast={toastItem} />}
      </ArkToaster>
    </Portal>
  );
};

const TOAST_ICONS = {
  loading: <Spinner />,
  success: <CircleCheckIcon />,
  error: <CircleAlertIcon />,
  info: <InfoIcon />,
  warning: <TriangleAlertIcon />,
} as const;

interface ToastItemProps extends React.ComponentProps<typeof ArkToast.Root> {
  /**
   * The toast item data
   */
  toast: ArkToast.Options;
}

export const ToastItem = (props: ToastItemProps) => {
  const { toast: toastData, className, ...rest } = props;

  const ToastIcon = toastData.type
    ? TOAST_ICONS[toastData.type as keyof typeof TOAST_ICONS]
    : null;

  const isExplicitClosable = toastData.closable === false;

  return (
    <ArkToast.Root
      className={cn(
        "z-(--z-index) translate-x-(--x) translate-y-(--y)",
        "relative",
        "w-[calc(100%-var(--viewport-offset-left))] sm:w-(--width)",
        "px-3.5 py-3",
        "flex items-start justify-between gap-1.5",
        "bg-popover",
        "select-none text-card-foreground text-sm",
        "rounded-lg border shadow-lg/5",
        "scale-(--scale) opacity-(--opacity)",
        "transition-all duration-250 will-change-[translate,opacity,scale]",
        "ease-[cubic-bezier(0.21,1.02,0.73,1)]",
        "data-[state=closed]:transition-[translate,scale,opacity]",
        "data-[state=closed]:duration-[300ms,300ms,150ms]",
        "data-[state=closed]:ease-[cubic-bezier(0.06,0.71,0.55,1)]",
        "motion-reduce:transition-none!",
        className
      )}
      data-slot="toast"
      {...rest}
    >
      <div className="flex items-start gap-1.5">
        <div
          className={cn(
            "in-data-[type=warning]:text-warning",
            "in-data-[type=success]:text-success",
            "in-data-[type=error]:text-destructive",
            "in-data-[type=info]:text-info",
            "[&_svg]:pointer-events-none [&_svg]:h-lh [&_svg]:w-4 [&_svg]:shrink-0"
          )}
          data-slot="toast-icon"
        >
          {ToastIcon}
        </div>

        <div className="flex flex-col gap-0.5">
          <ArkToast.Title
            className="font-medium text-sm"
            data-slot="toast-title"
          >
            {toastData.title}
          </ArkToast.Title>

          {toastData.description && (
            <ArkToast.Description
              className="text-muted-foreground text-sm"
              data-slot="toast-description"
            >
              {toastData.description}
            </ArkToast.Description>
          )}
        </div>
      </div>

      <div className="flex items-center gap-2">
        {toastData.action && (
          <ArkToast.ActionTrigger
            asChild
            data-slot="toast-action-trigger"
            onClick={toastData.action.onClick}
          >
            <Button size="sm" variant="secondary">
              {toastData.action.label}
            </Button>
          </ArkToast.ActionTrigger>
        )}

        {!isExplicitClosable && (
          <ArkToast.CloseTrigger asChild data-slot="toast-close-trigger">
            <Button
              aria-label="Close"
              className="opacity-64 hover:opacity-100"
              size="icon-xs"
              variant="ghost"
            >
              <XIcon />
            </Button>
          </ArkToast.CloseTrigger>
        )}
      </div>
    </ArkToast.Root>
  );
};
