INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_toggle-tooltip','Toggle Tooltip','toggle-tooltip','Overlays','Display information on click.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react"],"registryDependencies":["https://bits.dakik.co.uk/r/popover.json"],"file":{"path":"registry/react/components/toggle-tooltip.tsx","type":"registry:ui"}}','"use client";

