INSERT OR REPLACE INTO "component_doc" ("id","name","slug","category","description","props","code","preview","published","createdAt","updatedAt") VALUES ('cmp_tooltip','Tooltip','tooltip','Overlays','Display information on hover or focus.','{"type":"registry:ui","author":"Dakik Studio <https://dakik.co.uk>","dependencies":["@ark-ui/react"],"file":{"path":"registry/react/components/tooltip.tsx","type":"registry:ui"}}','"use client";

import { Portal } from "@ark-ui/react/portal";
